def check_max_k_fixed(n):
    max_k = -1
    for k in range(n):
        possible = False
        for s in range(n + 1):
            # Tutte's condition: m >= s+2 (since n is even, m and s have the same parity)
            # Actually, let's just use m >= s+1 and then check the parity.
            # m and s must have same parity because n is even.
            m_min = s + 1
            if (m_min % 2) != (s % 2):
                m_min += 1
            if s == 0:
                m_min = 2

            m_max = (n - s) // (k + 1)

            if m_max >= m_min:
                if k % 2 == 1:
                    # e(C_i, S) >= 1, so m <= k*s
                    if s > 0 and m_min <= k * s:
                        possible = True
                        break
                else:
                    # k is even.
                    if s == 0:
                        # m even, m >= 2, m(k+1) <= n
                        # since m_min is 2 and we need m even,
                        # and m_max is floor(n/(k+1)),
                        # we need there to be an even number in [m_min, m_max].
                        # But m_min is 2, so we just need m_max >= 2.
                        if m_max >= 2:
                            possible = True
                            break
                    else:
                        # s > 0, k > 0.
                        # m >= s+2, m(k+1) <= n-s.
                        # Also need m_pos >= 1 such that 2*m_pos <= k*s.
                        # Since k >= 2 and s >= 1, 2*1 <= k*s is always true.
                        # So we just need m_max >= m_min.
                        if m_max >= m_min:
                            possible = True
                            break
        if possible:
            max_k = max(max_k, k)
    return max_k

print(f"Max k for n=40: {check_max_k_fixed(40)}")
